package com.jnapanam.sportszone.usermanagement.controller;import com.jnapanam.sportszone.usermanagement.dto.ChangePasswordRequest;import com.jnapanam.sportszone.usermanagement.service.UserManagementService;import jakarta.validation.Valid;import java.util.UUID;import org.springframework.http.HttpStatus;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/profile")public class UserPasswordController{private final UserManagementService service;public UserPasswordController(UserManagementService s){service=s;}@PostMapping("/password")@ResponseStatus(HttpStatus.NO_CONTENT)public void change(Authentication a,@Valid@RequestBody ChangePasswordRequest r){service.changePassword(UUID.fromString(a.getName()),r);}}
